  if (street === 'flop') {
    const all = ['dry', 'wet', 'monotone', 'paired'].flatMap(shape => ['high', 'mid', 'low'].map(height => `${shape}_${height}`));
    return all.filter(value => texture === 'any' || value === texture || value.split('_').includes(texture));
  }
