  return MW3_SELECTOR_KEYS.every(key => key === 'texture'
    ? textureDomains(a[key], street).some(value => textureDomains(b[key], street).includes(value))
    : a[key] === 'any' || b[key] === 'any' || a[key] === b[key]);
