  let n = 0;
  for (let c = 4; c >= 1; c -= 1) for (let rank = 12; rank >= 0; rank -= 1) if (counts[rank] === c) byCount[n++] = rank;
  const top = byCount[0], second = n > 1 ? byCount[1] : -1;
