    let kicker = 12;
    while (kicker > 0 && (kicker === top || !counts[kicker])) kicker -= 1;
    return packed(7, top, kicker, 0, 0, 0);
  }
  if (counts[top] === 3 && counts[second] >= 2) return packed(6, top, second, 0, 0, 0);
