    for (let rank = 12; rank >= 0 && k < 5; rank -= 1) if (suitMask[flush] & (1 << rank)) kickers[k++] = rank;
    return packed(5, kickers[0], kickers[1], kickers[2], kickers[3], kickers[4]);
