  let s0 = 0, s1 = 0, s2 = 0, s3 = 0, s4 = 0, singles = 0;
  for (let rank = 12; rank >= 0; rank -= 1) if (counts[rank] === 1) {
    if (singles === 0) s0 = rank; else if (singles === 1) s1 = rank; else if (singles === 2) s2 = rank; else if (singles === 3) s3 = rank; else if (singles === 4) s4 = rank;
    singles += 1;
  }
  if (counts[top] === 3) return packed(3, top, s0, s1, 0, 0);
  if (counts[top] === 2 && counts[second] === 2) {
    let kicker = 12;
    while (kicker > 0 && (kicker === top || kicker === second || !counts[kicker])) kicker -= 1;
    return packed(2, top, second, kicker, 0, 0);
  }
  if (counts[top] === 2) return packed(1, top, s0, s1, s2, 0);
  return packed(0, s0, s1, s2, s3, s4);
}

// rows: [{hand, weight}] with weight in 0..1 per hand class.
export function weightedRange(rows) {
  return rows.flatMap(({ hand, weight }) => weight > 0 ? combosOf(hand).map(combo => ({ combo, weight })) : []);
}

export function equityVsRange(hand, range, samples, random) {
  if (!range.length) return null;
  const mine = combosOf(hand);
  const cumulative = [];
  let sum = 0;
  for (const item of range) { sum += item.weight; cumulative.push(sum); }
  let wins = 0;
  let total = 0;
  for (let i = 0; i < samples; i += 1) {
    const [a, b] = mine[i % mine.length];
    let villain;
    for (let tries = 0; tries < 50; tries += 1) {
      const x = random() * sum;
      let lo = 0, hi = cumulative.length - 1;
      while (lo < hi) { const mid = (lo + hi) >> 1; if (cumulative[mid] < x) lo = mid + 1; else hi = mid; }
      const combo = range[lo].combo;
      if (!combo.includes(a) && !combo.includes(b)) { villain = combo; break; }
    }
    if (!villain) continue;
    const used = new Set([a, b, ...villain]);
    const board = [];
    while (board.length < 5) { const card = deck[(random() * 52) | 0]; if (!used.has(card)) { used.add(card); board.push(card); } }
    const heroScore = evaluate([a, b, ...board]);
    const villainScore = evaluate([...villain, ...board]);
    wins += heroScore > villainScore ? 1 : heroScore === villainScore ? 0.5 : 0;
    total += 1;
  }
  return total ? wins / total : null;
}

// Share of the range's weight removed by holding this hand (averaged over its combos).
export function blockedShare(hand, range) {
  const all = range.reduce((acc, item) => acc + item.weight, 0);
  if (!all) return 0;
  const mine = combosOf(hand);
  const kept = mine.reduce((acc, [a, b]) => acc + range.reduce((s, item) => s + (item.combo.includes(a) || item.combo.includes(b) ? 0 : item.weight), 0), 0) / mine.length;
  return 1 - kept / all;
}

// Hero's share of the pot against several opponents, each drawn from its own weighted range.
export function equityVsRanges(hand, ranges, samples, random) {
  if (ranges.some(range => !range.length)) return null;
  const tables = ranges.map(range => {
    const cumulative = [];
    let sum = 0;
    for (const item of range) { sum += item.weight; cumulative.push(sum); }
    return { range, cumulative, sum };
  });
  const draw = ({ range, cumulative, sum }) => {
    const x = random() * sum;
    let lo = 0, hi = cumulative.length - 1;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (cumulative[mid] < x) lo = mid + 1; else hi = mid; }
    return range[lo].combo;
  };
  const mine = combosOf(hand);
  let share = 0, total = 0;
  for (let i = 0; i < samples; i += 1) {
    const [a, b] = mine[i % mine.length];
    const used = new Set([a, b]);
    const villains = [];
    for (const table of tables) {
      let combo;
      for (let tries = 0; tries < 50 && !combo; tries += 1) {
        const candidate = draw(table);
        if (!used.has(candidate[0]) && !used.has(candidate[1])) combo = candidate;
      }
      if (!combo) break;
      used.add(combo[0]); used.add(combo[1]);
      villains.push(combo);
    }
    if (villains.length !== tables.length) continue;
    const board = [];
    while (board.length < 5) { const card = deck[(random() * 52) | 0]; if (!used.has(card)) { used.add(card); board.push(card); } }
    const scores = [evaluate([a, b, ...board]), ...villains.map(v => evaluate([...v, ...board]))];
    const best = Math.max(...scores);
    if (scores[0] === best) share += 1 / scores.filter(score => score === best).length;
    total += 1;
  }
  return total ? share / total : null;
}

// Best-five ranking for 5–7 cards, isolated from the historical evaluator so
// repairing new continuation equities never silently regenerates old ranges.
// Cards use the existing rank*4+suit encoding; rank 0=2, rank12=A.
const counts = new Int8Array(13), suitCounts = new Int8Array(4), suitMasks = new Int16Array(4);
const straightHighs = new Int8Array(8192).fill(-1);
for (let mask = 0; mask < straightHighs.length; mask++) {
  for (let high = 12; high >= 4; high--) if (((mask >> (high - 4)) & 31) === 31) { straightHighs[mask] = high; break; }
  if (straightHighs[mask] < 0 && (mask & 0x100F) === 0x100F) straightHighs[mask] = 3;
}
const packed = (category, a = 0, b = 0, c = 0, d = 0, e = 0) => ((((category * 16 + a) * 16 + b) * 16 + c) * 16 + d) * 16 + e;
const topRanks = new Int8Array(5);
function top(mask, exclude1 = -1, exclude2 = -1) {
  topRanks.fill(0); let n = 0;
  for (let rank = 12; rank >= 0 && n < 5; rank--) if (mask & (1 << rank) && rank !== exclude1 && rank !== exclude2) topRanks[n++] = rank;
}

export function evaluateContinuation(cards) {
  if (cards.length < 5 || cards.length > 7) throw new Error("Continuation evaluator requires 5–7 cards");
  counts.fill(0); suitCounts.fill(0); suitMasks.fill(0);
  let mask = 0, lowSeen = 0, highSeen = 0;
  for (const card of cards) {
    if (!Number.isInteger(card) || card < 0 || card > 51) throw new Error("Invalid continuation card");
    const bit = 1 << (card & 31);
    if (card < 32) { if (lowSeen & bit) throw new Error("Duplicate continuation card"); lowSeen |= bit; }
    else { if (highSeen & bit) throw new Error("Duplicate continuation card"); highSeen |= bit; }
    const rank = card >> 2, suit = card & 3;
    counts[rank]++; suitCounts[suit]++; suitMasks[suit] |= 1 << rank; mask |= 1 << rank;
  }
  let flush = -1;
  for (let suit = 0; suit < 4; suit++) if (suitCounts[suit] >= 5) { flush = suit; break; }
  if (flush >= 0 && straightHighs[suitMasks[flush]] >= 0) return packed(8, straightHighs[suitMasks[flush]]);
  let quad = -1, trip = -1, pair = -1, secondPair = -1;
  for (let rank = 12; rank >= 0; rank--) {
    if (counts[rank] === 4) quad = rank;
    if (counts[rank] >= 3 && trip < 0) trip = rank;
    if (counts[rank] >= 2) { if (pair < 0) pair = rank; else if (secondPair < 0) secondPair = rank; }
  }
  if (quad >= 0) {
    let kicker = 12; while (kicker === quad || !counts[kicker]) kicker--;
    return packed(7, quad, kicker);
  }
  if (trip >= 0) {
    let fullPair = 12; while (fullPair >= 0 && (fullPair === trip || counts[fullPair] < 2)) fullPair--;
    if (fullPair >= 0) return packed(6, trip, fullPair);
  }
  if (flush >= 0) { top(suitMasks[flush]); return packed(5, topRanks[0], topRanks[1], topRanks[2], topRanks[3], topRanks[4]); }
  if (straightHighs[mask] >= 0) return packed(4, straightHighs[mask]);
  if (trip >= 0) { top(mask, trip); return packed(3, trip, topRanks[0], topRanks[1]); }
  if (secondPair >= 0) { top(mask, pair, secondPair); return packed(2, pair, secondPair, topRanks[0]); }
  if (pair >= 0) { top(mask, pair); return packed(1, pair, topRanks[0], topRanks[1], topRanks[2]); }
  top(mask); return packed(0, topRanks[0], topRanks[1], topRanks[2], topRanks[3], topRanks[4]);
}

