const outDir = join(mw3Root, '.local/postflop-ai/mw3/pilot-gate', `v${MW3_PILOT_AUTHORSHIP.version}-${inputs.fingerprint.slice(0, 12)}-${implementationHash.slice(0, 12)}-${verificationHash.slice(0, 12)}`);
