// Offline self-play/chip-flow verification of three dedicated saved policies.
// No HU reference bot, profile overlay, EV recommendation, or policy editing.
import { seededRandom, seedFor } from '../lib/equity.mjs';
import { mw3BoardRanges } from './mw3-audit.mjs';
import { makeMw3TupleSampler } from './mw3-joint-defence.mjs';
import { playMw3WithPolicies } from './mw3-runtime.mjs';
import { setMw3RankingCacheLimit } from './mw3-hand-features.mjs';
import { parseCards } from './model.mjs';
import { mw3Sha } from './mw3-inputs.mjs';
import pilot from '../data/postflop-ai-pilot.json' with { type: 'json' };
export const MW3_SIMULATION_VERSION = 1;
export const MW3_SIMULATION_SAMPLES = pilot.samples_per_board_profile_seat;

export function simulateMw3(inputs, policies, { samplesPerBoard = MW3_SIMULATION_SAMPLES,
  boardList = pilot.boards, onBoard = () => {} } = {}) {
  if (!Number.isInteger(samplesPerBoard) || samplesPerBoard < MW3_SIMULATION_SAMPLES) throw new Error('mw3 simulation cannot reduce the existing 10,000 samples per board');
  if (!Array.isArray(boardList) || !boardList.length || new Set(boardList.map(item => item?.cards)).size !== boardList.length ||
      boardList.some(item => !item || !['design', 'holdout'].includes(item.split))) throw new Error('Invalid mw3 simulation board list');
  const fullRepresentativeScope = JSON.stringify(boardList) === JSON.stringify(pilot.boards);
  const previousLimit = setMw3RankingCacheLimit(2048), results = [];
  try {
    for (const descriptor of boardList) {
      const flop = parseCards(descriptor.cards, 3), ranges = mw3BoardRanges(inputs, flop), sample = makeMw3TupleSampler(ranges, inputs.spot.seats);
      const seed = `mw3-simulation-v1|${inputs.fingerprint}|${descriptor.cards}`, random = seededRandom(seedFor(seed));
      const counts = { flop: {}, turn: {}, river: {} }, wins = Object.fromEntries(inputs.spot.seats.map(seat => [seat, 0]));
      let ties = 0, foldTerminals = 0, allInTerminals = 0, rakeTotal = 0;
      const finalStackTotals = Object.fromEntries(inputs.spot.seats.map(seat => [seat, 0]));
      for (let index = 0; index < samplesPerBoard; index++) {
        const hands = sample(random), blocked = new Set([...flop, ...Object.values(hands).flat()]);
        const available = Array.from({ length: 52 }, (_, card) => card).filter(card => !blocked.has(card));
        const turn = available.splice(Math.floor(random() * available.length), 1)[0];
        const river = available.splice(Math.floor(random() * available.length), 1)[0];
        const result = playMw3WithPolicies(inputs, policies, { hands, board: [...flop, turn, river], random });
        if (result.status !== 'done') throw new Error('mw3 self-play unexpectedly awaits input');
        const settlement = result.settlement;
        if (settlement.winners.length > 1) ties++; else wins[settlement.winner]++;
        if (result.table.streetState.end.type === 'fold') foldTerminals++;
        if (result.table.log.some(event => event.stackBb > 0 && event.amountBb >= event.stackBb)) allInTerminals++;
        rakeTotal += settlement.rakeBb;
        for (const seat of inputs.spot.seats) finalStackTotals[seat] += settlement.finalStacks[seat];
        for (const event of result.table.log) counts[event.street][event.action] = (counts[event.street][event.action] ?? 0) + 1;
      }
      const row = { board: descriptor.cards, split: descriptor.split, samples: samplesPerBoard, seed, wins, ties,
        foldTerminals, allInTerminals, rakeTotal, finalStackTotals, actionCounts: counts };
      results.push(row); onBoard(row);
    }
  } finally { setMw3RankingCacheLimit(previousLimit); }
  return { version: MW3_SIMULATION_VERSION, sourceHash: inputs.fingerprint, spot: inputs.spot.id,
    flopHash: mw3Sha(policies.flop), laterHash: mw3Sha(policies.later), samplesPerBoard, fullRepresentativeScope,
    tupleSampling: 'full_three_player_tuple_rejection', policyInterpretation: 'direct_saved_mix_with_observable_alias_sum',
    purpose: 'deterministic_self_play_chip_flow_not_ev_or_equilibrium_approval', results };
}

// Independent, pure accounting checks for saved simulation reports. This does not
// run the simulator, prove strategy quality, or replace deterministic replay.
import pilot from '../data/postflop-ai-pilot.json' with { type: 'json' };
const HASH = /^[a-f0-9]{64}$/;
const STREETS = ['flop', 'turn', 'river'];
const ACTIONS = ['check', 'fold', 'call', 'bet33', 'bet75', 'bet125', 'allin', 'raise'];
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const sameKeys = (value, expected) => object(value) && Object.keys(value).length === expected.length &&
  expected.every(key => Object.hasOwn(value, key));
const count = (value, limit) => Number.isSafeInteger(value) && value >= 0 && value <= limit;
const sum = values => values.reduce((total, value) => total + value, 0);
const fail = detail => { throw new Error(`Invalid mw3 simulation report: ${detail}`); };

export function validateMw3SimulationReport(report, { sourceHash, spotId, seats, potBb, stackBb,
  flopHash, laterHash, samplesPerBoard = 10000 } = {}) {
  if (![sourceHash, flopHash, laterHash].every(hash => typeof hash === 'string' && HASH.test(hash)) ||
      typeof spotId !== 'string' || !spotId || !Array.isArray(seats) || seats.length !== 3 ||
      new Set(seats).size !== 3 || seats.some(seat => typeof seat !== 'string' || !seat) ||
      !Number.isFinite(potBb) || potBb <= 0 || !Number.isFinite(stackBb) || stackBb <= 0 ||
      !Number.isSafeInteger(samplesPerBoard) || samplesPerBoard < 10000 ||
      !Number.isSafeInteger(samplesPerBoard * 27)) fail('trusted expected identity/geometry');
  if (!object(report) || report.version !== 1 || report.sourceHash !== sourceHash || report.spot !== spotId ||
      report.flopHash !== flopHash || report.laterHash !== laterHash || report.samplesPerBoard !== samplesPerBoard ||
      report.fullRepresentativeScope !== true || report.tupleSampling !== 'full_three_player_tuple_rejection' ||
      report.policyInterpretation !== 'direct_saved_mix_with_observable_alias_sum' ||
      report.purpose !== 'deterministic_self_play_chip_flow_not_ev_or_equilibrium_approval') fail('identity or scope');
  if (pilot.boards.length !== 12 || !Array.isArray(report.results) || report.results.length !== 12) fail('all twelve representative boards required');
  const initialTotal = potBb + 3 * stackBb, totalChips = samplesPerBoard * initialTotal;
  // Per-hand integer-cent wagers are exact; aggregate floating-point payouts can
  // accumulate tiny summation errors. This is 0.00001BB at 10,000 samples.
  const tolerance = Math.max(1e-6, samplesPerBoard * 1e-9);
  if (!Number.isFinite(totalChips)) fail('aggregate chip bound');
  for (const [index, expected] of pilot.boards.entries()) {
    const row = report.results[index], label = expected.cards;
    if (!object(row) || row.board !== expected.cards || row.split !== expected.split || row.samples !== samplesPerBoard ||
        row.seed !== `mw3-simulation-v1|${sourceHash}|${expected.cards}`) fail(`${label}: board, sample or seed identity`);
    if (!sameKeys(row.wins, seats) || !seats.every(seat => count(row.wins[seat], samplesPerBoard)) ||
        !count(row.ties, samplesPerBoard) || sum(Object.values(row.wins)) + row.ties !== samplesPerBoard) fail(`${label}: winner/tie counts`);
    if (!count(row.foldTerminals, samplesPerBoard) || !count(row.allInTerminals, samplesPerBoard) ||
        row.foldTerminals > sum(Object.values(row.wins))) fail(`${label}: terminal counts`);
    if (!sameKeys(row.actionCounts, STREETS)) fail(`${label}: street action counts`);
    let folds = 0, literalAllins = 0, callOrAggression = 0;
    for (const street of STREETS) {
      const actions = row.actionCounts[street];
      if (!object(actions) || Object.entries(actions).some(([action, value]) => !ACTIONS.includes(action) || !count(value, 9 * samplesPerBoard))) fail(`${label}/${street}: unknown or invalid action count`);
      const total = sum(Object.values(actions));
      // Three actors, one opening wager, at most two raises: no street exceeds
      // nine decisions, including the two possible checks before the first bet.
      if (total > 9 * samplesPerBoard || street === 'flop' && total < 3 * samplesPerBoard ||
          (actions.check ?? 0) > 3 * samplesPerBoard || (actions.raise ?? 0) > 2 * samplesPerBoard ||
          (actions.fold ?? 0) > 2 * samplesPerBoard ||
          sum(['bet33', 'bet75', 'bet125', 'allin'].map(action => actions[action] ?? 0)) > samplesPerBoard) fail(`${label}/${street}: impossible aggregate action count`);
      folds += actions.fold ?? 0;
      literalAllins += actions.allin ?? 0;
      callOrAggression += sum(['call', 'raise', 'bet33', 'bet75', 'bet125', 'allin'].map(action => actions[action] ?? 0));
    }
    // A fold win needs exactly two original players to have folded. A showdown
    // can have zero or one fold. Fold terminals and all-in terminals may overlap.
    if (folds < 2 * row.foldTerminals || folds > samplesPerBoard + row.foldTerminals ||
        literalAllins > 3 * row.allInTerminals || row.allInTerminals > callOrAggression) fail(`${label}: terminal/action accounting`);
    const minimumRake = Math.min(potBb * 0.05, 3) * samplesPerBoard;
    if (!Number.isFinite(row.rakeTotal) || row.rakeTotal < minimumRake - tolerance || row.rakeTotal > 3 * samplesPerBoard + tolerance ||
        !sameKeys(row.finalStackTotals, seats) || !seats.every(seat => Number.isFinite(row.finalStackTotals[seat]) &&
          row.finalStackTotals[seat] >= 0 && row.finalStackTotals[seat] <= totalChips + tolerance)) fail(`${label}: stack/rake bounds`);
    if (Math.abs(sum(Object.values(row.finalStackTotals)) + row.rakeTotal - totalChips) > tolerance) fail(`${label}: aggregate chip conservation`);
  }
  return report;
}

// Pure card/suit isomorphism. Card IDs are rank * 4 + cdhs suit; no Node dependencies.
export const ISOMORPHISM_VERSION = 1;
const RANKS = "23456789TJQKA", SUITS = "cdhs";
export const cardText = card => RANKS[card >> 2] + SUITS[card & 3];
export const suitPermutations = Object.freeze((function permutations(prefix = [], rest = [0, 1, 2, 3]) {
  return rest.length ? rest.flatMap(suit => permutations([...prefix, suit], rest.filter(value => value !== suit))) : [Object.freeze(prefix)];
})());

export function cardIds(value, count) {
  const cards = typeof value === "string" ? value.match(/../g)?.map(text => {
    if (!/^[2-9TJQKA][cdhs]$/.test(text)) throw new Error("Invalid card string");
    return RANKS.indexOf(text[0]) * 4 + SUITS.indexOf(text[1]);
  }) : value;
  if (!Array.isArray(cards) || cards.length !== count || typeof value === "string" && value.length !== count * 2 ||
      cards.some(card => !Number.isInteger(card) || card < 0 || card >= 52) || new Set(cards).size !== count) throw new Error("Invalid or duplicate cards");
  return [...cards];
}

export const mapCard = (card, permutation) => (card & ~3) + permutation[card & 3];
export const mapCards = (cards, permutation) => cards.map(card => mapCard(card, permutation));
export const invertSuits = permutation => {
  if (!Array.isArray(permutation) || permutation.length !== 4 || new Set(permutation).size !== 4 || permutation.some(suit => ![0, 1, 2, 3].includes(suit))) throw new Error("Invalid suit permutation");
  const inverse = [];
  permutation.forEach((suit, index) => { inverse[suit] = index; });
  return inverse;
};
// Highest rank first, lowest suit first within a pair. The minimal numeric tuple over S4
// is unique even on paired/trips boards. Permutation ties use the fixed S4 order.
const ordered = cards => [...cards].sort((a, b) => (b >> 2) - (a >> 2) || (a & 3) - (b & 3));
export function canonicalFlop(value) {
  const actual = cardIds(value, 3);
  let best = null, toCanonical = null;
  for (const permutation of suitPermutations) {
    const cards = ordered(mapCards(actual, permutation));
    if (!best || cards[0] < best[0] || cards[0] === best[0] && (cards[1] < best[1] || cards[1] === best[1] && cards[2] < best[2])) {
      best = cards; toCanonical = permutation;
    }
  }
  return { key: best.map(cardText).join(""), cards: best, toCanonical, fromCanonical: invertSuits(toCanonical) };
}

// Hole-card keys preserve high-rank-first anatomy and normalise pair ordering.
export function comboKey(value, permutation = [0, 1, 2, 3]) {
  return ordered(mapCards(cardIds(value, 2), permutation)).map(cardText).join("");
}
export function isCanonicalFlopKey(value) {
  try { return canonicalFlop(value).key === value; } catch { return false; }
}

let representatives;
export function canonicalFlops() {
  if (!representatives) {
    const keys = new Map();
    for (let a = 0; a < 50; a++) for (let b = a + 1; b < 51; b++) for (let c = b + 1; c < 52; c++) {
      const flop = canonicalFlop([a, b, c]);
      keys.set(flop.key, flop.cards);
    }
    representatives = [...keys].sort(([a], [b]) => a.localeCompare(b)).map(([key, cards]) => Object.freeze({ id: key, cards: Object.freeze(cards) }));
    if (representatives.length !== 1755) throw new Error(`Expected 1,755 flop classes, got ${representatives.length}`);
    Object.freeze(representatives);
  }
  return representatives;
}

export function remapFlopNode(view, permutation) {
  return { ...view, rows: view.rows.map(row => ({ ...row,
    combos: row.combos.map(combo => ({ ...combo, cards: comboKey(combo.cards, permutation) })) })) };
}
export const remapFlopNodes = (nodes, permutation) => Object.fromEntries(Object.entries(nodes).map(([key, node]) => [key, remapFlopNode(node, permutation)]));

